function memoize(fn) {
  const cache = new Map();
  return function(...args) {
    const key = JSON.stringify(args);
    if (cache.has(key)) return cache.get(key);
    const result = fn.apply(this, args);
    cache.set(key, result);
    return result;
  };
}

const memoFib = memoize(function fib(n) {
  if (n < 2) return n;
  return memoFib(n-1) + memoFib(n-2);
});
console.log(memoFib(40));

function trampoline(fn) {
  return function(...args) {
    let result = fn(...args);
    while (typeof result === 'function') result = result();
    return result;
  };
}

const factorial = trampoline(function fact(n, acc = 1) {
  return n <= 1 ? acc : () => fact(n - 1, n * acc);
});
console.log(factorial(10));

class Maybe {
  constructor(val) { this.val = val; }
  static of(val) { return new Maybe(val); }
  map(fn) {
    return this.val == null ? this : Maybe.of(fn(this.val));
  }
  toString() { return `Maybe(${this.val})`; }
}

