class Result {
  constructor(val, err) { this.val = val; this.err = err; }
  static ok(val) { return new Result(val, null); }
  static fail(err) { return new Result(null, err); }
  flatMap(fn) {
    return this.err ? this : fn(this.val);
  }
}

